function playerFrameVisual(character,key){const base=PLAYER_VISUALS[character]||PLAYER_VISUALS.kael,layout=PLAYER_FRAME_LAYOUT[key]||[1,base.ground,448];return{scale:base.scale*layout[0],origin:layout[1]/448,width:layout[2],height:448};}
