const KNIGHT_RAGE={windup:.28,travel:.90,recovery:.34,distance:1280,damage:200,depth:85,reach:96};
const KNIGHT_RAGE_DURATION=KNIGHT_RAGE.windup+KNIGHT_RAGE.travel+KNIGHT_RAGE.recovery;
function knightRagePose(t){if(t<KNIGHT_RAGE.windup)return Math.min(1,Math.floor(t/KNIGHT_RAGE.windup*2));if(t<KNIGHT_RAGE.windup+KNIGHT_RAGE.travel)return [2,3,4,3][Math.floor((t-KNIGHT_RAGE.windup)*18)%4];return Math.min(7,5+Math.floor((t-KNIGHT_RAGE.windup-KNIGHT_RAGE.travel)/KNIGHT_RAGE.recovery*3));}
const DODGE_INTERVAL=.75; // Per-player minimum start interval; prevents permanent invincibility.
const KNIGHT_BASH={duration:.90,repeatInterval:1.05,guard:.65};
const KNIGHT_BACKSTEP={duration:.60,guard:.42,distance:135};
const HUNTRESS_CLIPS=['idle','walk','slash','rise','finisher','air-slash','air-spin','air-finish','roll','jump','bow','air-bow','rage','hurt','pickup','grapple','win'];
const KNIFE_STRIKES=[{duration:.42,impact:.19,linkAt:.40,damage:19,range:118,clip:'slash'},{duration:.44,impact:.20,linkAt:.42,damage:23,range:128,clip:'rise'},{duration:.58,impact:.28,damage:34,range:145,clip:'finisher'}];
function knifePose(strike,t){return t<strike.impact?Math.min(3,Math.floor(Math.max(0,t)/strike.impact*4)):4+Math.min(3,Math.floor((t-strike.impact)/(strike.duration-strike.impact)*4));}
const AIR_KNIVES=[{duration:.40,impact:.18,linkAt:.29,damage:24,range:132,clip:'air-slash'},{duration:.46,impact:.22,linkAt:.34,damage:26,range:145,clip:'air-spin'},{duration:.54,impact:.26,damage:38,range:150,clip:'air-finish'}];
const BOW_DURATION=.70,BOW_RELEASE=.44,HUNTRESS_RAGE_DURATION=2.6;
// Bow grip in huntress-bow-05, transformed by the shared sprite anchor and scale.
const LYRA_BOW_VISUAL=playerFrameVisual('lyra','huntress-bow-05');
const LYRA_STANDING_MUZZLE={forward:(296-224)*LYRA_BOW_VISUAL.scale+28,height:(LYRA_BOW_VISUAL.origin*448-260)*LYRA_BOW_VISUAL.scale};
const animationIndex=(t,duration,count=8)=>Math.min(count-1,Math.floor(Math.max(0,t)/duration*count));
function huntressFrame(p){let clip='idle',i=0;
 if(p.state==='idle')i=Math.floor((p.idleTime||0)/.16)%8;
 else if(p.state==='walk'){clip='walk';i=Math.floor(p.walkDistance/19)%8;}
 else if(p.state==='attack'){clip=p.bowAttack?'bow':KNIFE_STRIKES[p.step].clip;i=p.bowAttack?animationIndex(p.t,BOW_DURATION):knifePose(KNIFE_STRIKES[p.step],p.t);}
 else if(p.state==='jump'){clip=p.airLanding?'jump':p.airAttack?(p.airHeavy?'air-bow':AIR_KNIVES[p.airStep].clip):'jump';i=p.airLanding?6+animationIndex(p.t-p.airLandT,.18,2):animationIndex(p.airAttack?p.airT:p.t,p.airAttack?(p.airHeavy?BOW_DURATION:AIR_KNIVES[p.airStep].duration):JUMP_DURATION);}
 else if(p.state==='dodge'){clip='roll';i=animationIndex(p.t,.42);}
 else if(p.state==='rage'){clip='rage';i=[.12,.25,.42,.55,1.0,1.65,2.4].filter(end=>p.t>=end).length;}
 else if(p.state==='pickup'){clip='pickup';i=animationIndex(p.t,PICKUP_DURATION);}
 else if(p.state==='grab'){clip='grapple';i=p.t<.15?0:p.t<.3?1:2;}
 else if(p.state==='throw'){clip='grapple';i=3+animationIndex(p.t,THROW_DURATION,5);}
 else if(['hurt','launched','down','dead'].includes(p.state)){clip='hurt';i=p.state==='hurt'?animationIndex(p.t,.35,3):p.state==='launched'?3+animationIndex(p.t,PLAYER_FLIGHT,2):p.state==='down'?(p.t<.5?4:5+animationIndex(p.t-.5,PLAYER_DOWN-.5,3)):4;}
 else if(p.state==='respawn'){clip='jump';i=p.t<.6?4:p.t<.78?6:7;}
 else if(p.state==='victory'){clip='win';i=Math.min(3,animationIndex(p.t,1.0,4));}
 return frameKey('huntress-'+clip,i);
}
function huntressJumpHeight(p){if(p.airLanding){const u=clamp((p.t-p.airLandT)/.18,0,1);return p.airLandHeight*(1-u*u*(3-2*u));}if(p.airAttack){const duration=p.airHeavy?BOW_DURATION:AIR_KNIVES[p.airStep].duration,u=clamp(p.airT/duration,0,1);if(p.airHeavy){if(p.airT<BOW_RELEASE)return p.airLift+10*Math.sin(Math.PI*p.airT/BOW_RELEASE);const v=clamp((p.airT-BOW_RELEASE)/(BOW_DURATION-BOW_RELEASE),0,1);return p.airLift*(1-v*v*(3-2*v));}if(p.airStep===2)return p.airLift*(1-u*u*(3-2*u));return Math.max(65,p.airLift)+18*Math.sin(Math.PI*u);}return 110*Math.sin(Math.PI*clamp((p.t-.10)/.62,0,1));}

const KNIGHT_CLIPS=['idle','walk','jump','down','cross','thrust','air-slash','air-spin','air-finish','bash','slam','backstep','hurt','pickup','grapple','win','rage'];
const KNIGHT_CLIP_FRAMES={walk:8,down:8,cross:9,thrust:12};
const KNIGHT_STRIKES=[{clip:'down',duration:.36,impact:.18,contact:4,linkAt:.34,damage:24,range:145},{clip:'cross',duration:.48,impact:.24,contact:4,linkAt:.46,damage:28,range:155},{clip:'thrust',duration:.56,impact:.28,contact:6,damage:36,range:170}];
const KNIGHT_AIR=[{clip:'air-slash',duration:.44,impact:.20,linkAt:.40,damage:26,range:150},{clip:'air-spin',duration:.48,impact:.23,linkAt:.44,damage:29,range:160},{clip:'air-finish',duration:.58,impact:.28,damage:40,range:170}];
function knightGroundPose(strike,t){const count=KNIGHT_CLIP_FRAMES[strike.clip],contact=strike.contact;return t<strike.impact?Math.min(contact-1,Math.floor(Math.max(0,t)/strike.impact*contact)):contact+Math.min(count-contact-1,Math.floor((t-strike.impact)/(strike.duration-strike.impact)*(count-contact)));}
const KNIGHT_WALK_STOPS=[26,48,66,88,114,136,154,176];
function knightWalkPose(distance){const phase=Math.max(0,distance||0)%176;return KNIGHT_WALK_STOPS.findIndex(stop=>phase<stop);}
function knightFrame(p){let clip='idle',i=0;const pose=(t,d,n=8)=>animationIndex(t,d,n);if(p.state==='walk'){clip='walk';i=knightWalkPose(p.walkDistance);}else if(p.state==='idle')i=Math.floor((p.idleTime||0)/.24)%8;else if(p.state==='attack'){clip=p.bash?'bash':KNIGHT_STRIKES[p.step].clip;i=p.bash?pose(p.t,.9):knightGroundPose(KNIGHT_STRIKES[p.step],p.t);}else if(p.state==='jump'){clip=p.airAttack?(p.airHeavy?'slam':KNIGHT_AIR[p.airStep].clip):'jump';i=pose(p.airAttack?p.airT:p.t,p.airAttack?(p.airHeavy?.78:KNIGHT_AIR[p.airStep].duration):JUMP_DURATION);}else if(p.state==='dodge'){clip='backstep';i=animationIndex(p.t,KNIGHT_BACKSTEP.duration);}else if(p.state==='rage'){clip='bash';i=knightRagePose(p.t);}else if(p.state==='pickup'){clip='pickup';i=pose(p.t,PICKUP_DURATION);}else if(p.state==='grab'){clip='grapple';i=Math.min(2,pose(p.t,.4));}else if(p.state==='throw'){clip='grapple';i=3+animationIndex(p.t,THROW_DURATION,5);}else if(p.state==='victory'){clip='win';i=pose(p.t,1.3);}else if(p.state==='respawn'){clip='jump';i=p.t<.6?4:p.t<.78?6:7;}else if(['hurt','launched','down','dead'].includes(p.state)){clip='hurt';i=p.state==='hurt'?animationIndex(p.t,.35,3):p.state==='launched'?1+animationIndex(p.t,PLAYER_FLIGHT,2):p.state==='down'?4+animationIndex(p.t,PLAYER_DOWN,4):4;}return frameKey('knight-'+clip,Math.min((KNIGHT_CLIP_FRAMES[clip]||8)-1,i));}
function knightJumpHeight(p){if(p.airAttack){const t=p.airT;if(p.airHeavy){if(t<.12)return p.airLift+15*Math.sin(Math.PI*t/.24);return Math.max(0,(p.airLift+15)*(1-clamp((t-.12)/.30,0,1)));}if(p.airStep===2)return p.airLift*(1-clamp(t/KNIGHT_AIR[2].duration,0,1));return Math.max(65,p.airLift)+12*Math.sin(Math.PI*clamp(t/KNIGHT_AIR[p.airStep].duration,0,1));}return 110*Math.sin(Math.PI*clamp((p.t-.10)/.62,0,1));}
const WIN_DURATION=2.1;
const selectionState={idleTime:0,t:0,celebrating:false,launch:false,activePlayer:0,players:[{character:null,hover:'kael',t:0,idleTime:0}]};
const allPlayersReady=()=>selectionState.players.length>0&&selectionState.players.every(player=>!!FIGHTERS[player.character]&&player.connected!==false)&&new Set(selectionState.players.map(player=>player.character)).size===selectionState.players.length;
const winPose=t=>[.12,.25,.38,.51,.64,.78,.96,1.22,1.52,1.72,1.92].filter(end=>t>=end).length;
function selectionFrame(player=selectionState.players[selectionState.activePlayer||0]){const character=player?.character||player?.hover||selectedFighter,celebrating=!!(player?.character||player?.preview),t=player?.t||0;if(character==='selene')return frameKey(celebrating?'witch-win':'witch-idle',celebrating?animationIndex(t,1.1,4):Math.floor((player?.idleTime||0)/.22)%4);if(character==='garran')return frameKey(celebrating?'knight-win':'knight-idle',celebrating?animationIndex(t,1.3):Math.floor((player?.idleTime||0)/.24)%8);if(character==='lyra')return frameKey(celebrating?'huntress-win':'huntress-idle',celebrating?(t>=WIN_DURATION?3:animationIndex(t,WIN_DURATION)):Math.floor((player?.idleTime||0)/.16)%8);return celebrating?frameKey('hero-win',t>=WIN_DURATION?8:winPose(t)):frameKey('hero-idle',Math.floor((player?.idleTime||0)/.16)%8);}
