function heroFrame(p){if(isWitch(p))return witchFrame(p);if(isKnight(p))return knightFrame(p);if(isHuntress(p))return huntressFrame(p);if(p.state==='victory')return frameKey('hero-win',Math.min(8,winPose(p.t)));if(p.state==='pickup')return frameKey('hero-pickup',Math.min(7,Math.floor(p.t/PICKUP_DURATION*8)));if(p.state==='launched')return frameKey('hero-knockdown',Math.min(3,Math.floor(p.t/PLAYER_FLIGHT*4)));if(p.state==='down')return frameKey('hero-knockdown',4+Math.min(3,Math.floor(p.t/PLAYER_DOWN*4)));if(p.state==='idle')return frameKey('hero-idle',Math.floor((p.idleTime||0)/.16)%8);if(p.state==='respawn')return frameKey('hero-jump',p.t<.6?5:p.t<.78?6:7);if(p.state==='dead')return frameKey('base',5);if(p.state==='grab')return frameKey('hero-grapple',p.t<.12?0:p.t<.3?1:2);if(p.state==='throw')return frameKey('hero-grapple',3+Math.min(4,Math.floor(p.t/THROW_DURATION*5)));if(p.state==='rage')return frameKey('hero-rage',ragePose(p.t));if(p.state==='jump'&&p.airLanding)return frameKey('hero-jump',p.t-p.airLandT<.09?6:7);if(p.state==='jump'&&p.airAttack)return frameKey(airStrikeFor(p).clip,airStrikeFor(p).frames[Math.min(7,Math.floor(p.airT/airStrikeFor(p).duration*8))]);if(p.state==='jump')return frameKey('hero-jump',Math.min(7,Math.floor(p.t/JUMP_DURATION*8)));if(p.state==='walk')return frameKey('hero-walk',Math.floor(p.walkDistance/(186/16))%16);if(p.state==='attack'&&Number.isInteger(p.link))return frameKey(COMBO_LINKS[p.link].clip,Math.min(7,Math.floor(p.t/COMBO_LINKS[p.link].duration*8)));if(p.state==='attack')return frameKey(strikeFor(p).clip,Math.min(11,Math.floor(p.t/strikeFor(p).duration*12)));if(p.state==='dodge')return frameKey('hero-slide',Math.min(7,Math.floor(p.t/.36*8)));return frameKey('base',p.state==='hurt'?5:0)}
// Shared swept projectile/body collision in world x, ground lane y and height z.
// Future projectile types use the same helper; jumping changes the body height, not eligibility.
function projectileBodyContact(from,to,actor,{enemy=false,halfWidth=22,laneDepth=23,halfHeight=0}={}){
 const lift=enemy?enemyHeight(actor):jumpHeight(actor)+rageHeight(actor)+playerThrownHeight(actor)+respawnHeight(actor);
 const bodyHeight=enemy?(actor.kind==='dog'?80:actor.kind==='king'?210:160):160;
 let enter=0,exit=1;for(const [a,b,low,high] of [[from.x,to.x,actor.x-halfWidth,actor.x+halfWidth],[from.y,to.y,actor.y-laneDepth,actor.y+laneDepth],[from.z,to.z,lift+5-halfHeight,lift+bodyHeight+halfHeight]]){
  const d=b-a;if(Math.abs(d)<1e-8){if(a<low||a>high)return null;}else{const u=(low-a)/d,v=(high-a)/d;enter=Math.max(enter,Math.min(u,v));exit=Math.min(exit,Math.max(u,v));if(enter>exit)return null;}
 }return enter;
}
