let lastCommanderVariant=null;
function chooseCommanderVariant(){let previous=lastCommanderVariant;try{const saved=window.localStorage?.getItem('killquest-last-commander');if(COMMANDER_VARIANTS.includes(saved))previous=saved;}catch{}const choices=COMMANDER_VARIANTS.filter(v=>v!==previous),choice=choices[Math.floor(Math.random()*choices.length)];lastCommanderVariant=choice;try{window.localStorage?.setItem('killquest-last-commander',choice);}catch{}return choice;}
function commanderFrame(e){let i=16,extra=null;if(e.state==='walk'||e.state==='entering')i=Math.floor(e.walkDistance/16)%6;else if(e.state==='command')i=17;else if(e.state==='parry'){extra=e.t<COMMANDER.parrySetup?4+Math.min(3,Math.floor(e.t/COMMANDER.parrySetup*4)):7;}else if(e.state==='counter')extra=e.t<.07?8:e.t<.14?9:e.t<.30?10:11;else if(e.state==='attack'){const step=e.commanderStep||0,strike=COMMANDER_COMBO[step];if(step===1)extra=Math.min(3,Math.floor(e.t/strike.duration*4));else i=step===2?12+Math.min(3,Math.floor(e.t/strike.duration*4)):6+Math.min(5,Math.floor(e.t/strike.duration*6));}else if(e.state==='hurt')i=18;else if(e.state==='grabbed')i=e.lift>10?20:19;else if(e.state==='thrown')i=e.t<FLIGHT_DURATION*.72?21:22;else if(e.state==='down'||e.state==='pitfall')i=22;else if(e.state==='dead')i=23;return frameKey('commander-'+(e.variant||COMMANDER_VARIANTS[0])+(extra===null?'':'-combat'),extra??i);}
