function rebelFrame(a){let i=a.kind==='spearman'&&a.state==='ready'?11:null;const t=a.t||0,walk=a.state==='walk'||a.state==='entering';if(walk)i=Math.floor((a.walkDistance||0)/17)%6;else if(a.state==='attack'){if(a.kind==='commander'){const step=a.commanderStep||0;i=6+step*4+Math.min(3,Math.floor(t/COMMANDER_COMBO[step].duration*4));}else{i=6+Math.min(5,Math.floor(t/(a.kind==='guard'?.95:a.kind==='bulwark'?BULWARK.attackDuration:a.kind==='spearman'?SPEARMAN.duration:CROSSBOW.attackDuration)*6));}}else if(a.kind==='commander'){if(a.state==='parry')i=t<COMMANDER.parrySetup?18:19;else if(a.state==='counter')i=t<.16?20:21;else if(a.state==='hurt')i=22;else if(['down','thrown','dead','pitfall'].includes(a.state))i=23;}else if(a.kind==='crossbowman'){if(a.state==='reload')i=12+Math.min(5,Math.floor((1-(a.reloadRemaining??CROSSBOW.reloadDuration)/CROSSBOW.reloadDuration)*6));else if(a.state==='hurt')i=18+Math.min(1,Math.floor(t/.18));else if(a.state==='thrown')i=20+Math.min(1,Math.floor(t/FLIGHT_DURATION*2));else if(['dead','down','pitfall'].includes(a.state))i=23;}else if(a.kind==='spearman'){if(a.state==='hurt')i=14+Math.min(1,Math.floor(t/.18));else if(a.state==='thrown')i=16+Math.min(1,Math.floor(t/FLIGHT_DURATION*2));else if(a.state==='down')i=19;else if(['dead','pitfall'].includes(a.state))i=23;}else{if(a.state==='guard')i=a.guardFlash>0?14:12;else if(a.state==='hurt')i=16+Math.min(1,Math.floor(t/.18));else if(a.state==='thrown')i=18+Math.min(1,Math.floor(t/FLIGHT_DURATION*2));else if(a.state==='down')i=21;else if(['dead','pitfall'].includes(a.state))i=23;}return i===null?frameKey('rebel-'+a.kind,Math.floor((a.idleTime||0)/.22)%6):frameKey('rebel-'+a.kind+'-combat',i);}

