function enemyHudTargets(model){return model.enemies.filter(e=>e.kind!=='king'&&e.hp<(e.maxHp||65)&&e.state!=='entering'&&(e.hp>0||e.t<1.1)).map(e=>({id:e.id,name:(e.elite?'VETERAN ':'')+ENEMY_NAMES[e.kind||'dagger'],number:(e.id%5)+1,health:clamp(e.hp/(e.maxHp||65),0,1),dead:e.hp<=0}));}
function renderCombatHud(model,view){const targets=enemyHudTargets(model),live=new Set(targets.map(e=>e.id));view.enemyHud??=new Map();for(const [id,node] of view.enemyHud)if(!live.has(id)){node.remove();view.enemyHud.delete(id);}for(const e of targets){let node=view.enemyHud.get(e.id);if(!node){node=document.createElement('div');node.className='enemyHealth';const label=document.createElement('b'),track=document.createElement('div'),fill=document.createElement('i');label.className='enemyName';track.className='enemyTrack';track.appendChild(fill);node.append(label,track);$('enemyHud').appendChild(node);view.enemyHud.set(e.id,node);}node.querySelector('b').textContent=e.name+' · '+e.number;node.querySelector('i').style.width=(e.health*100)+'%';node.classList.toggle('defeated',e.dead);node.setAttribute('role','progressbar');node.setAttribute('aria-label',e.name+' '+e.number);node.setAttribute('aria-valuemin','0');node.setAttribute('aria-valuemax','100');node.setAttribute('aria-valuenow',Math.round(e.health*100));}const lives=$('lives');lives.setAttribute('aria-label',model.p.lives+' lives remaining');for(let i=0;i<3;i++)lives.children[i].classList.toggle('spent',i>=model.p.lives);}
