function enemyDeathCue(e){if(e.isNpc){if(e.npcDeathVoice)return;e.npcDeathVoice=true;}if(e.kind==='king'){if(e.deathAudioPlayed)return;e.deathAudioPlayed=true;soundCue('boss-death',{x:e.x,actor:'king',gain:.9});}else if(e.kind==='dog'){if(e.deathAudioPlayed)return;e.deathAudioPlayed=true;soundCue('dog-death',{x:e.x,actor:'dog-'+e.id,gain:.9});}else soundCue('bandit-death',{x:e.x,actor:'bandit-'+e.id});}
