 villageConversation(){const lines=[['BANDITS',"Don't draw this out. You have nowhere to go and the city guard is holed up in the main quarter. Your valuables now!"],['TOWNSFOLK',"Hey! What about them?!"],['BANDITS',"These chumps? They're next!"]];if(this.villageStep<3)return {speaker:lines[this.villageStep][0],text:lines[this.villageStep][1],replies:[]};const text={kael:'You wish, cockroach. You can take my axe to your face!',garran:'You have that much of death wish?',lyra:'You guys never learn, do you?',selene:"I don't have time for the homeless."};return {speaker:'THE WARBAND',text:'',replies:this.players.map(p=>({player:p.id,character:p.character,name:FIGHTERS[p.character].name,text:text[p.character]}))};}
